/** Regenerates docs/TOOLS.md from the registry: npx tsx scripts/gen-tools-doc.ts */
import { writeFileSync } from "node:fs";
import { TOOL_DEFINITIONS } from "../src/tools/registry";
import { CATEGORIES } from "../src/tools/categories";

const lines = [
  "# Tool catalogue",
  "",
  `${TOOL_DEFINITIONS.length} tools. *Processing*: **browser** = runs entirely on the visitor's device; **server** = needs a minimal server request; **network** = contacts network endpoints.`,
  "",
  "Generated by `scripts/gen-tools-doc.ts` — do not edit by hand.",
  "",
];
for (const c of CATEGORIES) {
  const tools = TOOL_DEFINITIONS.filter((t) => t.category === c.id);
  lines.push(`## ${c.name} (${tools.length})`, "", "| Tool | URL | Processing | Key limitations |", "|---|---|---|---|");
  for (const t of tools) lines.push(`| ${t.name} | \`/tools/${t.id}\` | ${t.processing} | ${t.notes[0].replace(/\|/g, "\\|")} |`);
  lines.push("");
}
const browser = TOOL_DEFINITIONS.filter((t) => t.processing === "browser").length;
lines.push(`**${browser} of ${TOOL_DEFINITIONS.length} tools (${((browser / TOOL_DEFINITIONS.length) * 100).toFixed(1)} %) run entirely in the browser.**`, "");
writeFileSync("docs/TOOLS.md", lines.join("\n"));
console.log("docs/TOOLS.md written");
